import XCTest
@testable import NotchFlow

@MainActor
final class ClipboardPrivacyTests: XCTestCase {
    func testSkipsMarkedPasteboards() {
        let markers = [
            "org.nspasteboard.ConcealedType",
            "org.nspasteboard.AutoGeneratedType",
            "org.nspasteboard.TransientType",
            "com.agilebits.onepassword",
            "de.petermaurer.TransientPasteboardType",
            "com.typeit4me.clipping",
            "Pasteboard generator type",
        ]
        for marker in markers {
            XCTAssertTrue(
                ClipboardManager.shouldSkipCapture(types: ["public.utf8-plain-text", marker], frontmostBundleID: "com.apple.TextEdit"),
                marker
            )
        }
    }

    func testSkipsCopiesWhileAPasswordManagerIsFrontmost() {
        for bundleID in ["com.1password.1password", "com.bitwarden.desktop", "org.keepassxc.keepassxc", "com.apple.Passwords"] {
            XCTAssertTrue(ClipboardManager.shouldSkipCapture(types: ["public.utf8-plain-text"], frontmostBundleID: bundleID), bundleID)
        }
    }

    func testRecordsOrdinaryCopies() {
        XCTAssertFalse(ClipboardManager.shouldSkipCapture(types: ["public.utf8-plain-text"], frontmostBundleID: "com.apple.Safari"))
        XCTAssertFalse(ClipboardManager.shouldSkipCapture(types: ["public.url", "public.utf8-plain-text"], frontmostBundleID: nil))
        XCTAssertFalse(ClipboardManager.shouldSkipCapture(types: [], frontmostBundleID: nil))
    }
}
